/**
 * MCP Server Factory
 *
 * Creates a configured McpServer with all 9 OneSource documentation tools.
 * Shared by stdio (server.ts), HTTP (http-server.ts), CLI (cli.ts), and Vercel (api/mcp.js).
 */
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { createRequire } from 'node:module';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { loadContent } from './content/loader.js';
import { SearchIndex } from './content/indexer.js';
import { loadSchemaData } from './content/schema-loader.js';
import { searchDocsSchema, handleSearchDocs } from './tools/search-docs.js';
import { getQueryReferenceSchema, handleGetQueryReference } from './tools/get-query-reference.js';
import { getTypeDefinitionSchema, handleGetTypeDefinition } from './tools/get-type-definition.js';
import { listExamplesSchema, handleListExamples } from './tools/list-examples.js';
import { listSupportedChainsSchema, handleListSupportedChains } from './tools/list-supported-chains.js';
import { getFilterReferenceSchema, handleGetFilterReference } from './tools/get-filter-reference.js';
import { getPaginationGuideSchema, handleGetPaginationGuide } from './tools/get-pagination-guide.js';
import { getSchemaOverviewSchema, handleGetSchemaOverview } from './tools/get-schema-overview.js';
import { getAuthenticationGuideSchema, handleGetAuthenticationGuide } from './tools/get-authentication-guide.js';
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const DEFAULT_DATA_DIR = join(__dirname, '..', 'data');
const require = createRequire(import.meta.url);
const VERSION = require('../package.json').version;
/**
 * Load all content from the data directory. Use this to pre-load once for long-running servers.
 */
export function loadData(dataDir) {
    const dir = dataDir ?? DEFAULT_DATA_DIR;
    const skillsDir = join(dir, 'skills');
    const schemaPath = join(dir, 'schema-data.json');
    const sections = loadContent(skillsDir);
    const index = new SearchIndex(sections);
    const schema = loadSchemaData(schemaPath);
    return { sections, index, schema };
}
/**
 * Create a configured MCP server with all OneSource documentation tools.
 * @param dataDirOrData - Either a directory path containing `schema-data.json` and `skills/`,
 *   or a pre-loaded LoadedData object (for long-running servers that pre-load once).
 */
export function createMcpServer(dataDirOrData) {
    let sections;
    let index;
    let schema;
    if (typeof dataDirOrData === 'object' && dataDirOrData !== null) {
        ({ sections, index, schema } = dataDirOrData);
    }
    else {
        ({ sections, index, schema } = loadData(dataDirOrData));
    }
    const server = new McpServer({
        name: 'onesource-docs',
        version: VERSION,
    });
    server.tool('search_docs', 'Search OneSource documentation by keyword. Returns the top 5 matching sections.', searchDocsSchema.shape, async (input) => ({
        content: [{ type: 'text', text: handleSearchDocs(input, index) }],
    }));
    server.tool('get_query_reference', 'Get full reference for a OneSource root GraphQL query — arguments, filters, return type. There are 12 root queries: address, addresses, block, blocks, contract, contracts, nft, nfts, token, tokens, transaction, transactions.', getQueryReferenceSchema.shape, async (input) => ({
        content: [{ type: 'text', text: handleGetQueryReference(input, schema) }],
    }));
    server.tool('get_type_definition', 'Get the schema definition for a GraphQL type, enum, scalar, input, or interface. Returns fields, values, and descriptions.', getTypeDefinitionSchema.shape, async (input) => ({
        content: [{ type: 'text', text: handleGetTypeDefinition(input, schema) }],
    }));
    server.tool('list_examples', 'List or search working GraphQL examples. Without a topic, returns a summary of all available examples. With a topic, returns full example content matching that keyword.', listExamplesSchema.shape, async (input) => ({
        content: [{ type: 'text', text: handleListExamples(input, sections) }],
    }));
    server.tool('list_supported_chains', 'List all blockchain networks supported by OneSource with endpoint URLs.', listSupportedChainsSchema.shape, async () => ({
        content: [{ type: 'text', text: handleListSupportedChains() }],
    }));
    server.tool('get_filter_reference', 'Get all filter fields and operators for a list query (e.g. transactions, tokens).', getFilterReferenceSchema.shape, async (input) => ({
        content: [{ type: 'text', text: handleGetFilterReference(input, schema) }],
    }));
    server.tool('get_pagination_guide', 'Get the cursor-based pagination pattern with examples for a list query.', getPaginationGuideSchema.shape, async (input) => ({
        content: [{ type: 'text', text: handleGetPaginationGuide(input, schema) }],
    }));
    server.tool('get_schema_overview', 'Get a high-level summary of the entire GraphQL schema — all queries, types, enums, and scalars.', getSchemaOverviewSchema.shape, async () => ({
        content: [{ type: 'text', text: handleGetSchemaOverview(schema) }],
    }));
    server.tool('get_authentication_guide', 'Get the authentication guide — API key format, endpoints, headers, and common mistakes.', getAuthenticationGuideSchema.shape, async () => ({
        content: [{ type: 'text', text: handleGetAuthenticationGuide() }],
    }));
    return server;
}
// Re-export transport for consumers (Vercel, etc.) that need it
export { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';
